TD = src('TreasuryDirect (U.S. Department of the Treasury)', 'https://www.treasurydirect.gov/savings-bonds/i-bonds/', 'I bonds must be held at least 12 months; if cashed before 5 years, the last 3 months of interest are lost; Treasury bills are sold at a discount and pay face value at maturity.')

# ---------------------------------------------------------------- S24
S(24, 'Compound interest', 'Calculate compound interest and compare it with simple interest',
  main=[
    q('$1,000 earns 10% annually, compounded once per year. Assuming the rate stays constant and there are no deposits or withdrawals, what is the balance after two years?', '$1,210',
      [('$1,100', 'Applies one year of interest only'), ('$1,200', 'Uses simple interest'), ('$1,220', 'Adds 10% of $1,200 in year two')],
      intro='When interest is compounded annually, interest is calculated on the current balance, including previously earned interest. For a constant annual rate, A = P(1 + r)^t.',
      fb='A = 1,000(1.10)^2 = 1,000 × 1.21 = $1,210. Year 1 adds $100; year 2 adds 10% of $1,100 = $110.', calc=1000 * 1.1 ** 2, sub='A = P(1 + r)^t'),
    q('$500 is deposited at 4% interest compounded annually. How much interest is earned in the SECOND year?', '$20.80',
      [('$20.00', 'Uses simple interest on the original $500'), ('$40.80', 'Gives total interest for two years'), ('$540.80', 'Gives the balance after two years')],
      intro='With compounding, each year\'s interest is figured on the balance at the start of that year. Year 1 interest is added to the principal, so year 2 interest is larger.',
      fb='Year 1: $500 × 0.04 = $20, balance $520. Year 2: $520 × 0.04 = $20.80.', calc=500 * 1.04 * 0.04, sub='Year-by-year interest'),
    q('$5,000 earns 4% per year for 3 years. How much MORE interest does annual compounding earn than simple interest?', '$24.32',
      [('$624.32', 'Gives the compound interest, not the difference'), ('$600.00', 'Gives the simple interest'), ('$200.00', 'Gives one year of simple interest')],
      intro='Simple interest is figured only on the principal: I = Prt. Compound interest is figured on the growing balance: A = P(1 + r)^t, and interest = A − P. The gap between them grows over time.',
      fb='Simple: 5,000 × 0.04 × 3 = $600. Compound: 5,000(1.04)^3 = $5,624.32, so $624.32 of interest. Difference: $24.32.', calc=5000 * 1.04 ** 3 - 5000 - 600, sub='Simple vs compound'),
    q('$2,000 is invested at 6% compounded annually for 10 years. What is the balance (nearest cent)?', '$3,581.70',
      [('$3,200.00', 'Uses simple interest'), ('$3,378.96', 'Uses 9 years'), ('$2,120.00', 'Uses one year')],
      intro='To use A = P(1 + r)^t: write the rate as a decimal, add 1, raise to the number of years first (exponents before multiplication), then multiply by P.',
      fb='A = 2,000(1.06)^10 ≈ 2,000 × 1.790848 = $3,581.70.', calc=2000 * 1.06 ** 10, sub='Using the formula'),
    q('Two accounts both start with $1,000 at 5% for 20 years. One pays simple interest; one compounds annually. Why does the compound account end higher?', 'It earns interest on earlier interest as well as on the principal',
      [('Its stated rate is really higher than 5%, which the bank does not show', 'Thinks the rate differs'), ('Simple interest accounts charge fees that reduce the balance', 'Invents fees'), ('Compounding adds a bonus deposit each year', 'Invents a deposit')],
      fb='Same rate, same time: compounding wins because interest itself earns interest.', sub='Why compounding grows faster'),
  ],
  back=[
    concept('Interest on interest', 'Compound interest makes sense only after students see that added interest becomes part of the balance.', [
      q('$100 earns 10% interest for one year. What is the balance after one year?', '$110',
        [('$10', 'Gives the interest only'), ('$100', 'Ignores the interest'), ('$1,000', 'Multiplies by 10')],
        intro='After interest is added, the balance = old balance + interest. That new balance is what earns interest next year when interest compounds.',
        fb='$100 + $10 = $110.', calc=110, sub='Adding interest'),
      q('$100 earns 10% interest and grows to $110 after year one. In year two, the $110 earns 10% again. How much interest is earned in year two?', '$11',
        [('$10', 'Uses the original $100'), ('$21', 'Adds both years\' interest'), ('$121', 'Gives the new balance')],
        intro='With compound interest, the rate applies to the whole current balance, including interest already earned.',
        fb='$110 × 0.10 = $11.', calc=11, sub='Interest on the new balance'),
      q('Which statement describes COMPOUND interest?', 'Interest is earned on the principal and on interest already added',
        [('Interest is earned only on the original deposit', 'Describes simple interest'), ('Interest is paid only when the account is closed', 'Confuses compounding with payout timing'), ('Interest is the same dollar amount every year, figured on the deposit', 'Describes simple interest')],
        intro='Simple interest: interest on the principal only, the same dollar amount each year. Compound interest: interest on the principal plus accumulated interest, growing each year.',
        fb='Compound interest earns "interest on interest."', sub='Definition'),
      q('Multiplying by 1.05 is the same as adding what percent?', '5%',
        [('105%', 'Treats the multiplier as the percent'), ('0.05%', 'Misreads the decimal'), ('50%', 'Misreads the decimal')],
        intro='Increasing an amount by r% is the same as multiplying it by (1 + r), with r as a decimal. Adding 5% means multiplying by 1.05.',
        fb='× 1.05 = original + 5% of the original.', calc=5, sub='Growth factor'),
      q('Which expression gives $800 after 3 years at 5% compounded annually?', '800(1.05)^3',
        [('800 × 0.05 × 3', 'Gives simple interest only'), ('800 + 1.05 × 3', 'Adds instead of multiplying'), ('800(0.05)^3', 'Uses the rate instead of 1 + rate')],
        fb='Multiply by the growth factor 1.05 once per year: 800(1.05)^3.', sub='Writing the expression'),
    ]),
    math('Evaluate numerical expressions with whole-number exponents', 'A = P(1 + r)^t requires evaluating a power.', 'grade_6', 40),
    math('Evaluate expressions that use parentheses', 'The order of operations matters: compute 1 + r first, then the power, then multiply.', 'grade_5', 1),
    math('Recognize constant-percent growth', 'Compound interest is growth by a constant percent per year.', 'algebra_1', 55),
    math('Find a percent of a quantity', 'Each year\'s interest is a percent of the balance.', 'grade_6', 10),
  ],
  go=[
    deeper('Reading an exponential growth model', [
      q('An account balance is modeled by A = 1,500(1.05)^t, where t is years. What does 1.05 tell you?', 'The balance grows 5% each year',
        [('The balance grows $1.05 each year', 'Reads the factor as dollars'), ('The balance grows 105% each year', 'Reads the factor as the rate'), ('The account pays a $1,500 bonus every 5 years', 'Misreads the parameters')],
        intro='In A = P(1 + r)^t, P is the starting amount and (1 + r) is the growth factor per period. A factor of 1.05 means each year\'s balance is 105% of the year before, a 5% increase.',
        fb='1.05 = 1 + 0.05, so the balance grows 5% per year.', sub='Growth factor'),
      q('In A = 1,500(1.05)^t, what does 1,500 represent?', 'The starting balance',
        [('The interest earned each year', 'Confuses the start with interest'), ('The balance after 5 years', 'Confuses the start with a later value'), ('The maximum balance allowed', 'Invents a limit')],
        intro='In an exponential model A = P(1 + r)^t, the value when t = 0 is P, because any number raised to the power 0 equals 1.',
        fb='At t = 0, A = 1,500(1) = 1,500, the starting balance.', sub='Initial value'),
      q('Using A = 1,500(1.05)^t, what is the balance after 4 years (nearest cent)?', '$1,823.26',
        [('$1,800.00', 'Uses simple interest'), ('$1,575.00', 'Uses one year'), ('$1,736.44', 'Uses three years')],
        fb='1,500 × 1.05^4 = 1,500 × 1.21550625 = $1,823.26.', calc=1500 * 1.05 ** 4, sub='Evaluating the model'),
      q('Which model shows a balance that starts at $600 and grows 3% per year?', 'A = 600(1.03)^t',
        [('A = 600(0.03)^t', 'Uses the rate as the factor'), ('A = 600 + 1.03t', 'Uses a linear model'), ('A = 3(600)^t', 'Swaps the roles')],
        fb='Start 600, growth factor 1 + 0.03 = 1.03.', sub='Writing a model'),
      q('A savings balance doubled from $800 to $1,600 over some years. Which type of growth model fits a fixed annual compound rate?', 'Exponential: the balance multiplies by the same factor each year',
        [('Linear: the balance adds the same number of dollars every single year', 'Describes simple interest'), ('Quadratic: the balance follows a parabola', 'Wrong model family'), ('Constant: the balance never changes', 'Ignores growth')],
        fb='Compound interest multiplies by a constant factor each period: exponential growth.', sub='Model type'),
    ]),
    deeper('Working backward: present value', [
      q('Kim wants $10,000 in 5 years. Her account earns 5% compounded annually. How much must she deposit today (nearest cent)?', '$7,835.26',
        [('$7,500.00', 'Uses simple interest'), ('$9,500.00', 'Subtracts one year of interest'), ('$12,762.82', 'Grows $10,000 forward instead of discounting')],
        intro='Present value is how much money today grows to a target amount later. Solve A = P(1 + r)^t for P: P = A ÷ (1 + r)^t.',
        fb='P = 10,000 ÷ 1.05^5 = 10,000 ÷ 1.2762816 ≈ $7,835.26.', calc=10000 / 1.05 ** 5, sub='Present value'),
      q('Which expression gives the deposit needed today to have $5,000 in 3 years at 4% compounded annually?', '5,000 ÷ (1.04)^3',
        [('5,000 × (1.04)^3', 'Grows forward instead of discounting'), ('5,000 − 0.04 × 3', 'Subtracts a percent'), ('5,000 ÷ (0.04)^3', 'Uses the rate instead of 1 + rate')],
        intro='To find the deposit needed today, divide the future amount by the growth factor raised to the number of years: P = A ÷ (1 + r)^t.',
        fb='Dividing by (1.04)^3 undoes three years of 4% growth.', sub='Writing present value'),
      q('Why is the deposit needed today SMALLER than the future goal?', 'Interest will make up the difference over time',
        [('Banks add a bonus to every goal', 'Invents a bonus'), ('Inflation automatically adds extra money to savings accounts each year', 'Misunderstands inflation'), ('The goal amount shrinks every year', 'Reverses the idea')],
        intro='Money deposited today earns interest, and the interest compounds, so a smaller amount today can grow into a larger amount later.',
        fb='Compound growth turns a smaller deposit into the larger future amount.', sub='Why present value is smaller'),
      q('If the rate were higher than 5%, how would the deposit needed today for a $10,000 goal in 5 years change?', 'It would be smaller',
        [('It would be larger', 'Reverses the effect'), ('It would stay the same', 'Ignores the rate'), ('It would equal $10,000', 'Ignores interest')],
        intro='In P = A ÷ (1 + r)^t, a higher rate makes the denominator larger.',
        fb='Faster growth means less money is needed today.', sub='Effect of the rate'),
      q('Jay can deposit $4,000 today at 6% compounded annually. Will he reach $5,000 within 4 years?', 'Yes; 4,000(1.06)^4 ≈ $5,049.91',
        [('No; 4,000(1.06)^4 ≈ $4,960', 'Arithmetic error'), ('No; he will have exactly $4,960', 'Uses simple interest'), ('Yes; he will have $5,600', 'Uses 10% per year')],
        fb='1.06^4 ≈ 1.262477, so 4,000 × 1.262477 ≈ $5,049.91, just over $5,000.', calc=4000 * 1.06 ** 4, pick=-1, sub='Checking a goal'),
    ]),
  ],
  nat=('Saving', 'Compound interest: calculate and explain how interest compounds'), nj=['PB', 'FI'],
  status='stable', extra=['Present value of a savings goal'])

# ---------------------------------------------------------------- S25
S(25, 'Compounding frequency and APY', 'Calculate balances with monthly, quarterly, or daily compounding and use APY to compare accounts',
  main=[
    q('$1,000 is deposited at 6% annual interest compounded monthly. What is the balance after 1 year (nearest cent)?', '$1,061.68',
      [('$1,060.00', 'Uses annual compounding'), ('$1,005.00', 'Applies one month only'), ('$2,012.20', 'Uses 6% per month')],
      intro='When interest compounds n times per year, each period uses the rate r/n, and there are n·t periods: A = P(1 + r/n)^(nt). Monthly: n = 12. Quarterly: n = 4. Daily: n = 365.',
      fb='Monthly rate: 0.06 ÷ 12 = 0.005. A = 1,000(1.005)^12 ≈ $1,061.68.', calc=1000 * 1.005 ** 12, sub='Monthly compounding'),
    q('An account pays 6% compounded monthly. What is its APY (nearest hundredth of a percent)?', '6.17%',
      [('6.00%', 'Ignores compounding'), ('0.50%', 'Gives the monthly rate'), ('72.00%', 'Multiplies the rate by 12')],
      intro='APY (annual percentage yield) is the actual percent growth in one year including compounding: APY = (1 + r/n)^n − 1. Banks must show APY so savers can compare accounts with different compounding.',
      fb='(1.005)^12 − 1 ≈ 0.061678 = 6.17%.', calc=(1.005 ** 12 - 1) * 100, sub='Finding APY'),
    q('Account A pays 4.9% compounded daily. Account B pays 5.0% compounded once a year. Which earns more in a year?', 'Account A: its APY is about 5.02%',
      [('Account B, because 5.0% is higher than 4.9%', 'Compares rates without compounding'), ('They earn exactly the same', 'Assumes compounding cancels the difference'), ('Account B, because daily compounding lowers the yield', 'Misunderstands compounding')],
      intro='A slightly lower rate compounded more often can produce a higher yield. Compare accounts by APY, not by the stated rate.',
      fb='A: (1 + 0.049/365)^365 − 1 ≈ 5.02%. B: 5.00%. Account A earns slightly more.', sub='Comparing frequency and rate'),
    q('$2,000 earns 4% annual interest compounded quarterly for 2 years. What is the balance (nearest cent)?', '$2,165.71',
      [('$2,163.20', 'Uses annual compounding'), ('$2,160.00', 'Uses simple interest'), ('$2,020.00', 'Applies one quarter only')],
      fb='Quarterly rate 0.04 ÷ 4 = 0.01; periods 4 × 2 = 8. A = 2,000(1.01)^8 ≈ $2,165.71.', calc=2000 * 1.01 ** 8, sub='Quarterly compounding'),
    q('In A = P(1 + r/n)^(nt), what is n for interest compounded quarterly?', '4',
      [('3', 'Uses months in a quarter'), ('12', 'Uses monthly compounding'), ('0.25', 'Uses the fraction of a year')],
      fb='Quarterly means 4 times a year, so n = 4.', calc=4, sub='Compounding periods'),
  ],
  back=[
    concept('Rates per year and per period', 'Compounding-frequency problems require splitting an annual rate into a per-period rate.', [
      q('An annual rate of 6% is compounded monthly. What rate applies each month?', '0.5%',
        [('6%', 'Uses the annual rate'), ('72%', 'Multiplies by 12'), ('2%', 'Divides by 3')],
        intro='A stated annual rate is split evenly across compounding periods: periodic rate = annual rate ÷ number of periods per year.',
        fb='6% ÷ 12 = 0.5% per month.', calc=0.5, sub='Monthly rate'),
      q('An annual rate of 8% is compounded quarterly. What is the quarterly rate?', '2%',
        [('8%', 'Uses the annual rate'), ('32%', 'Multiplies by 4'), ('0.67%', 'Divides by 12')],
        intro='Quarterly means four periods per year: periodic rate = annual rate ÷ 4.',
        fb='8% ÷ 4 = 2% per quarter.', calc=2, sub='Quarterly rate'),
      q('How many compounding periods are in 3 years of monthly compounding?', '36',
        [('3', 'Counts years'), ('12', 'Counts one year'), ('15', 'Adds 12 + 3')],
        intro='Total periods = periods per year × years.',
        fb='12 × 3 = 36.', calc=36, sub='Number of periods'),
      q('Write 0.5% as a decimal.', '0.005',
        [('0.05', 'Moves the decimal one place too few'), ('0.5', 'Does not convert'), ('5', 'Moves the wrong way')],
        intro='To write a percent as a decimal, divide by 100.',
        fb='0.5 ÷ 100 = 0.005.', calc=0.005, sub='Small percents'),
      q('Which compounds MORE often: daily or monthly?', 'Daily',
        [('Monthly', 'Reverses frequency'), ('They are the same', 'Ignores frequency'), ('Neither compounds', 'Misunderstands compounding')],
        fb='Daily = 365 times per year; monthly = 12.', sub='Frequency'),
    ]),
    math('Use the properties of exponents to transform exponential expressions', 'Rewriting an annual rate as a monthly factor uses exponent properties.', 'algebra_1', 16),
    math('Interpret growth and decay rates using exponent properties', 'APY compares yearly growth factors from different compounding periods.', 'algebra_1', 46),
    math('Divide multi-digit decimals', 'Periodic rates divide the annual rate by the number of periods.', 'grade_6', 20),
  ],
  go=[
    deeper('How much does compounding frequency matter?', [
      q('$10,000 earns 5% for one year. Compounded annually, the balance is $10,500. Compounded monthly, it is about $10,511.62. Compounded daily, it is about $10,512.67. What pattern do these show?', 'More frequent compounding helps, but by smaller amounts each step',
        [('Daily compounding doubles the interest', 'Overstates the effect'), ('Compounding frequency makes no difference at all to the year-end balance', 'Ignores the small gains'), ('Monthly compounding earns less than annual', 'Misreads the numbers')],
        intro='Compounding more often adds a little more interest, because interest starts earning interest sooner. The gain from annual to monthly is noticeable; from monthly to daily it is tiny.',
        fb='Annual → monthly adds $11.62; monthly → daily adds only $1.05.', sub='Diminishing gains'),
      q('Comparing savings accounts, which factor usually matters MORE than compounding frequency?', 'The interest rate itself',
        [('Whether interest compounds daily or monthly', 'Overweights a small effect'), ('The number of branches in other states', 'Rarely affects earnings'), ('The day of the month interest posts', 'Minor effect')],
        intro='A 1-percentage-point difference in rate changes yearly interest far more than switching between monthly and daily compounding.',
        fb='At 5% vs 4%, the rate difference is about $100 a year on $10,000; frequency differences are often a few dollars.', sub='What matters most'),
      q('How much more does $10,000 earn in one year at 5% compounded annually than at 4% compounded annually?', '$100',
        [('$1', 'Uses 0.01%'), ('$1,000', 'Uses 10%'), ('$10', 'Uses 0.1%')],
        intro='At annual compounding, one year of interest is principal × rate.',
        fb='$500 − $400 = $100.', calc=10000 * 0.05 - 10000 * 0.04, sub='Rate difference'),
      q('A bank advertises 4.88% APY compounded daily. Another advertises 4.90% APY compounded monthly. Which pays more?', 'The 4.90% APY account',
        [('The 4.88% APY account, because daily compounding is better', 'Double-counts compounding'), ('They pay exactly the same', 'Ignores the APY difference'), ('It cannot be determined from APY', 'Misunderstands APY')],
        intro='APY already includes the effect of compounding, so the higher APY earns more, whatever the compounding frequency.',
        fb='APY already includes compounding; 4.90% > 4.88%.', sub='Using APY'),
      q('An account with a $5 monthly fee pays 4.50% APY. About how much does $2,000 earn in a year after fees?', '$30',
        [('$90', 'Ignores fees'), ('$60', 'Gives only the fees'), ('$150', 'Adds fees')],
        intro='Fees subtract from what an account earns. On small balances, a monthly fee can wipe out most of the interest.',
        fb='Interest: $2,000 × 0.045 = $90. Fees: $5 × 12 = $60. Net: $30.', calc=2000 * 0.045 - 60, sub='Fees vs interest'),
    ]),
    deeper('Promotional and variable rates', [
      q('A bank offers 5.25% APY for the first 3 months, then the regular 1.00% APY. On $4,000, about how much interest is earned in the first year (simple estimate by period)?', '$82.50',
        [('$210.00', 'Uses 5.25% for the whole year'), ('$40.00', 'Uses 1% for the whole year'), ('$52.50', 'Counts only the promotional months')],
        intro='A promotional ("teaser") rate applies only for a limited time, then drops to the regular rate. Estimate interest for each period separately.',
        fb='First 3 months: 4,000 × 0.0525 × 0.25 = $52.50. Next 9 months: 4,000 × 0.01 × 0.75 = $30. Total ≈ $82.50.', calc=4000 * 0.0525 * 0.25 + 4000 * 0.01 * 0.75, sub='Teaser rates'),
      q('Which question should Ana ask about a "limited-time" savings rate?', 'What rate applies after the promotion ends?',
        [('Is the rate higher than my checking account\'s?', 'Compares with the wrong account'), ('Can I open the account online?', 'Focuses on convenience, not the rate'), ('Is this rate guaranteed for as long as I keep the account?', 'Assumes promotional rates last forever')],
        intro='Promotional rates are advertised prominently, but the rate after the promotion decides what you earn over a longer time.',
        fb='The post-promotion rate determines long-term earnings.', sub='Reading offers', how=True),
      q('A savings account\'s variable rate drops from 4% to 3% after six months. On $6,000, about how much interest is earned that year?', '$210',
        [('$240', 'Uses 4% for the whole year'), ('$180', 'Uses 3% for the whole year'), ('$420', 'Adds both full-year amounts')],
        intro='When a rate changes partway through the year, figure the interest for each part of the year separately.',
        fb='6,000 × 0.04 × 0.5 = $120; 6,000 × 0.03 × 0.5 = $90; total ≈ $210.', calc=6000 * 0.04 * 0.5 + 6000 * 0.03 * 0.5, sub='Variable rates'),
      q('Why might a bank lower its savings rate?', 'Market interest rates fell',
        [('A customer deposited too much', 'Not how rates are set'), ('The account was opened online', 'Not a reason for changes'), ('Federal law requires yearly cuts', 'Invents a law')],
        intro='Savings rates tend to follow market interest rates, which change with economic conditions and Federal Reserve policy.',
        fb='Banks adjust variable rates as market rates change.', sub='Why rates change'),
      q('Which product LOCKS a savings rate for a set term?', 'A certificate of deposit',
        [('A regular savings account', 'Usually variable'), ('A money market account', 'Usually variable'), ('A checking account', 'Usually little or no interest')],
        intro='Savings products differ: regular savings and money market accounts usually have variable rates that can change at any time; a certificate of deposit (CD) usually keeps a fixed rate until it matures, in exchange for leaving the money in place.',
        fb='CDs usually have a fixed rate for their term.', sub='Fixed vs variable'),
    ]),
  ],
  nat=('Saving', 'Compare savings options using APY and compounding'), nj=['FI', 'PB'],
  status='stable', extra=['Evaluating promotional savings rates'])

# ---------------------------------------------------------------- S26
S(26, 'Time, doubling, and the Rule of 72', 'Estimate doubling time with the Rule of 72 and explain why starting early matters',
  main=[
    q('Using the Rule of 72, about how long does it take money to double at 6% compounded annually?', '12 years',
      [('6 years', 'Uses the rate as the years'), ('16.7 years', 'Uses 100 ÷ 6'), ('4.3 years', 'Divides 72 by 6 then by 2.8')],
      intro='The Rule of 72 is a quick estimate: years to double ≈ 72 ÷ (annual interest rate as a percent). It works best for rates between about 4% and 12% and gives an approximation, not an exact answer.',
      fb='72 ÷ 6 = 12 years.', calc=72 / 6, sub='Rule of 72'),
    q('About what annual rate would double money in 9 years, by the Rule of 72?', '8%',
      [('9%', 'Uses the years as the rate'), ('0.125%', 'Divides 9 by 72'), ('81%', 'Multiplies 9 by 9')],
      intro='The Rule of 72 also works backward: rate ≈ 72 ÷ years to double.',
      fb='72 ÷ 9 = 8%.', calc=72 / 9, sub='Finding the rate'),
    q('$5,000 grows at 7% compounded annually. How much MORE does it grow to after 40 years than after 30 years (nearest dollar)?', '$36,811',
      [('$3,500', 'Uses 10 years of simple interest'), ('$38,061', 'Gives the 30-year balance'), ('$74,872', 'Gives the 40-year balance')],
      intro='Compound growth speeds up over time because each year\'s growth is a percent of a larger balance. The last decade can add more than all the earlier decades combined.',
      fb='40 years: 5,000(1.07)^40 ≈ $74,872. 30 years: 5,000(1.07)^30 ≈ $38,061. Difference ≈ $36,811.', calc=5000 * 1.07 ** 40 - 5000 * 1.07 ** 30, tol=0.5, sub='Effect of time'),
    q('Use the Rule of 72 to estimate what $1,000 grows to in 36 years at 8% compounded annually.', 'About $16,000',
      [('About $8,000', 'Counts three doublings'), ('About $3,880', 'Uses simple interest'), ('About $4,000', 'Counts doublings as additions')],
      intro='Each "doubling period" multiplies the balance by 2. Count the doubling periods in the time span, then double that many times.',
      fb='72 ÷ 8 = 9 years per doubling; 36 ÷ 9 = 4 doublings: $1,000 → $2,000 → $4,000 → $8,000 → $16,000. (Exact: about $15,968.)', sub='Counting doublings'),
    q('Why is the Rule of 72 called an estimate?', 'It approximates the exact compound-interest result',
      [('It only works for simple interest', 'Misunderstands the rule'), ('It gives the exact answer for every interest rate and every time period', 'Overstates its accuracy'), ('It is a legal limit on interest rates', 'Confuses it with a law')],
      fb='It is a shortcut; the exact answer comes from A = P(1 + r)^t.', sub='Limits of the rule'),
  ],
  back=[
    concept('Doubling and repeated doubling', 'Doubling-time reasoning depends on understanding repeated multiplication by 2.', [
      q('$500 doubles once. What is the new amount?', '$1,000',
        [('$502', 'Adds 2'), ('$250', 'Halves'), ('$2,500', 'Multiplies by 5')],
        intro='To double means to multiply by 2.',
        fb='$500 × 2 = $1,000.', calc=1000, sub='Doubling'),
      q('$500 doubles three times. What is the final amount?', '$4,000',
        [('$1,500', 'Adds 500 three times'), ('$3,000', 'Multiplies by 6'), ('$2,000', 'Doubles twice')],
        intro='Doubling three times multiplies by 2 × 2 × 2 = 2^3 = 8.',
        fb='$500 × 8 = $4,000.', calc=4000, sub='Repeated doubling'),
      q('If money doubles every 10 years, how many times does it double in 30 years?', '3 times',
        [('30 times', 'Counts years'), ('10 times', 'Counts years per doubling'), ('2 times', 'Arithmetic error')],
        intro='Number of doublings = total years ÷ years per doubling.',
        fb='30 ÷ 10 = 3 doublings.', calc=3, sub='Counting doublings'),
      q('Starting with $100, which is larger after 30 years: adding $100 each year, or doubling every 10 years?', 'Adding $100 a year: $3,100 vs $800',
        [('Doubling every 10 years: $800 vs $3,100', 'Assumes doubling always wins'), ('They are equal at $3,100', 'Arithmetic error'), ('Doubling every 10 years: $3,200 vs $3,100', 'Counts five doublings instead of three')],
        intro='Steady additions grow by the same dollar amount each year (linear growth). Doubling multiplies the amount (exponential growth). Exponential growth starts slowly but eventually passes linear growth.',
        fb='Adding: $100 + 30 × $100 = $3,100. Doubling: $100 × 2^3 = $800. Over a longer time doubling wins: after 60 years, $6,400 vs $6,100.', sub='Linear vs doubling'),
      q('Which statement about compound growth is TRUE?', 'Growth is faster in later years because the balance is larger',
        [('Growth is fastest in the first year', 'Reverses the pattern'), ('Growth is the same number of dollars every year', 'Describes simple interest'), ('Growth stops after 10 years', 'Invents a limit')],
        fb='Each year adds a percent of a larger balance, so dollar growth speeds up.', sub='Accelerating growth'),
    ]),
    math('Write arithmetic and geometric sequences', 'Repeated doubling is a geometric sequence.', 'algebra_1', 50),
    math('Observe that exponential growth eventually exceeds linear growth', 'Compound growth eventually outpaces steady additions.', 'algebra_1', 57),
  ],
  go=[
    deeper('Starting early', [
      q('Saver A invests $2,000 a year from age 25 to 34 (10 years), then stops. Saver B invests $2,000 a year from 35 to 64 (30 years). Both earn 7% a year. By 65, A has about $210,000 and B about $189,000. How much did each CONTRIBUTE?', 'A: $20,000; B: $60,000',
        [('A: $210,000; B: $189,000', 'Confuses balances with contributions'), ('A: $60,000; B: $20,000', 'Swaps the savers'), ('Both: $40,000', 'Averages the contributions')],
        intro='Starting early gives money more years to compound. Someone who saves for a few early years can end up with more than someone who saves much longer but starts later. (These examples assume a steady 7% return; real investment returns vary and are not guaranteed.)',
        fb='A: 10 × $2,000 = $20,000. B: 30 × $2,000 = $60,000.', sub='Contributions'),
      q('Saver A contributed $20,000 and ended with about $210,000. Saver B contributed $60,000 and ended with about $189,000. Why did A end with more?', 'A\'s money had more years to compound',
        [('A earned a higher rate', 'Both earned the same assumed rate'), ('B paid higher taxes', 'Not in the example'), ('A contributed more money in total than B did', 'A contributed less')],
        intro='Compounding rewards time. Money invested earlier has more years for its earnings to earn more.',
        fb='Same rate, but A\'s dollars compounded for 30–40 years.', sub='Why time matters'),
      q('Saver A contributed $20,000 and ended with about $210,000. About how much of A\'s $210,000 came from growth rather than contributions?', 'About $190,000',
        [('About $20,000', 'Gives contributions'), ('About $210,000', 'Gives the total'), ('About $230,000', 'Adds instead of subtracting')],
        fb='$210,000 − $20,000 ≈ $190,000 of growth.', calc=190000, sub='Growth vs contributions'),
      q('A 17-year-old with a summer job wonders whether saving $500 now matters. At 7% a year, about what does $500 grow to in 48 years (nearest hundred, using the Rule of 72)?', 'About $13,000',
        [('About $500', 'Ignores growth'), ('About $2,180', 'Uses simple interest'), ('About $4,000', 'Counts too few doublings')],
        intro='At about 7%, money doubles roughly every 72 ÷ 7 ≈ 10.3 years.',
        fb='48 ÷ 10.3 ≈ 4.7 doublings; 2^4.7 ≈ 26, so about $500 × 26 ≈ $13,000. (Exact at 7%: 500 × 1.07^48 ≈ $12,800.)', sub='Small amounts early'),
      q('Which assumption in "start early" examples should a careful reader remember?', 'Real investment returns vary and are not guaranteed',
        [('Returns are guaranteed by the government', 'Overstates protection'), ('Every year earns exactly 7%, so results are certain', 'Treats an average as certain'), ('Starting early never matters', 'Rejects the main lesson')],
        fb='The lesson about time holds, but actual yearly returns can be higher, lower, or negative.', sub='Assumptions'),
    ]),
    deeper('The cost of waiting', [
      q('$1,000 invested at 6% for 36 years doubles about how many times (Rule of 72)?', '3 times',
        [('6 times', 'Uses 36 ÷ 6'), ('2 times', 'Arithmetic error'), ('12 times', 'Gives years per doubling')],
        intro='Years to double ≈ 72 ÷ rate. Number of doublings = years invested ÷ years per doubling.',
        fb='72 ÷ 6 = 12 years per doubling; 36 ÷ 12 = 3 doublings.', calc=3, sub='Doublings'),
      q('$1,000 invested at 6% doubles about every 12 years. Waiting 12 years to invest it, with a fixed retirement date, means ending with about…', 'half as much',
        [('the same amount', 'Ignores lost compounding'), ('twice as much', 'Reverses the effect'), ('12% less', 'Uses the years as a percent')],
        intro='At a given rate, one fewer doubling period at the end means one fewer doubling: the final balance is about half as large.',
        fb='Losing one doubling period cuts the result by about half.', sub='Lost doubling'),
      q('$1,000 grows at 6% for 36 years to about $8,000. If Jen invests the $1,000 at 6% but waits 12 years, so it grows for 24 years, about how much will she have?', 'About $4,000',
        [('About $8,000', 'Ignores the delay'), ('About $2,000', 'Removes two doublings'), ('About $7,000', 'Subtracts 12% of the total')],
        fb='24 years ÷ 12 = 2 doublings: $1,000 → $2,000 → $4,000.', sub='Effect of waiting'),
      q('Which factor does a young saver control MOST?', 'How early and how consistently they save',
        [('The stock market\'s yearly return', 'Not controllable'), ('The inflation rate', 'Not controllable'), ('Interest rates set by the Federal Reserve', 'Not controllable')],
        intro='Savers cannot control market returns, inflation, or interest rates. They can control when they start, how much they save, and how consistently they save.',
        fb='Time and consistency are within the saver\'s control.', sub='Controllable factors'),
      q('Two friends each save $100 a month. One starts at 22, the other at 32. Both stop at 65 and earn the same rate. Which statement is TRUE?', 'The earlier saver will very likely end with much more',
        [('They will end with the same amount', 'Ignores time'), ('The later saver will end with more', 'Reverses the effect'), ('Saving monthly removes the effect of starting time completely', 'Misunderstands compounding')],
        fb='Ten extra years of contributions and compounding produce a much larger balance.', sub='Monthly savers'),
    ]),
  ],
  nat=('Saving', 'Explain how time and compounding affect savings growth'), nj=['PB', 'FP'],
  status='stable', extra=['Rule of 72 estimates'])

# ---------------------------------------------------------------- S27
S(27, 'Savings options: high-yield savings, CDs, and money market accounts', 'Choose a savings product by safety, liquidity, and return',
  main=[
    q('What is a certificate of deposit (CD)?', 'A deposit left for a set term at a usually fixed rate',
      [('A stock that pays the same fixed dividend to owners every month', 'Confuses a CD with a stock'), ('A checking account with free checks', 'Confuses a CD with checking'), ('A loan that a bank gives to students', 'Confuses a CD with a loan')],
      intro='A certificate of deposit (CD) is a bank or credit union deposit that you agree to leave for a set term, such as 6 months or 5 years. In return, it usually pays a fixed rate. Taking money out before the term ends usually costs an early-withdrawal penalty. CDs are insured deposits up to the legal limit.',
      fb='A CD is a time deposit with a set term and usually a fixed rate.', sub='CDs'),
    q('Max\'s $5,000 CD pays 4.5% simple interest. The penalty for early withdrawal is 90 days of interest. About how much is the penalty (use 365 days in a year)?', '$55.48',
      [('$225.00', 'Uses a full year of interest'), ('$18.49', 'Uses 30 days'), ('$4.50', 'Misreads the rate')],
      intro='Early-withdrawal penalties are often stated as a number of days or months of interest. Penalty ≈ principal × rate × (days ÷ 365).',
      fb='5,000 × 0.045 × 90/365 ≈ $55.48.', calc=5000 * 0.045 * 90 / 365, sub='Early-withdrawal penalty'),
    q('Which statement about a money market DEPOSIT account (at a bank) and a money market FUND (at a brokerage) is TRUE?', 'Only the deposit account is FDIC insured',
      [('Both are FDIC insured', 'Thinks the similar names mean the same protection'), ('Only the fund is FDIC insured', 'Reverses the facts'), ('Neither can ever lose value, because both are offered by banks', 'Overstates the safety of the fund')],
      intro='A money market deposit account is a bank deposit, insured up to the legal limit. A money market fund is a mutual fund that invests in short-term debt. It aims to keep a stable value but is not FDIC insured and can, rarely, lose value.',
      fb='The bank account is a deposit (insured); the fund is an investment (not FDIC insured).', sub='Money market accounts vs funds'),
    q('Lily will need $3,000 for college fees in exactly 12 months, and she will not touch it before then. Which choice fits best?', 'A 12-month CD at an insured bank',
      [('A 5-year CD with a large early-withdrawal penalty', 'Term too long'), ('A stock fund, for the highest possible return', 'Value can fall right before she needs it'), ('Her checking account, which pays no interest', 'Earns nothing')],
      intro='Match the product to when you need the money. Money needed on a known date can go in a CD whose term ends by that date. Money you may need any time belongs in a savings account.',
      fb='A 12-month CD matches the timeline and keeps the money safe.', sub='Matching the term'),
    q('Which choice keeps emergency money BOTH safe and quickly available?', 'A high-yield savings account at an insured bank',
      [('A 3-year CD that charges an early-withdrawal penalty', 'Penalty to access'), ('A collectible card collection', 'Hard to sell at a known price'), ('A stock index fund', 'Value can drop when needed')],
      fb='Insured savings combine safety with quick access (liquidity).', sub='Liquidity'),
  ],
  back=[
    concept('Liquidity: how quickly money can be used', 'Choosing a savings product depends on trading access (liquidity) against return.', [
      q('What does "liquidity" mean in personal finance?', 'How quickly money can be used without losing value',
        [('How much interest an account pays each year, as a percent', 'Confuses liquidity with return'), ('How much water a bank uses', 'Literal misreading'), ('How large an account balance is', 'Confuses liquidity with size')],
        intro='Liquidity describes how easily and quickly something can be turned into cash you can spend, without losing value. Cash and checking are very liquid; a house is not.',
        fb='Liquidity = quick access without loss of value.', sub='Definition'),
      q('Which is MOST liquid?', 'Money in a checking account',
        [('A house', 'Takes time to sell'), ('A 5-year certificate of deposit', 'Penalty to withdraw early'), ('A car', 'Takes time to sell; value uncertain')],
        intro='Checking account money can be spent today. Selling a house or car, or ending a CD early, takes time or costs money.',
        fb='Checking money is available immediately.', sub='Ranking liquidity'),
      q('Why do longer-term CDs often pay higher rates than savings accounts?', 'You give up access to the money for longer',
        [('They are not insured', 'CDs are insured deposits'), ('Banks are required to pay more on CDs by law', 'Invents a law'), ('CD rates change every day', 'Most CD rates are fixed')],
        intro='Savers usually earn more for accepting less liquidity, such as locking money in a CD for a longer term.',
        fb='Less liquidity is usually rewarded with a higher rate.', sub='Trade-off'),
      q('Which money should be kept the MOST liquid?', 'An emergency fund',
        [('Savings for retirement in 40 years', 'Long horizon'), ('A college fund for a newborn', 'Long horizon'), ('Money for a house in 10 years', 'Long horizon')],
        fb='Emergency money must be available on short notice.', sub='Matching liquidity to goals'),
      q('A 2-year CD pays 4%; a savings account pays 3.5%. On $1,000 for one year, about how much more does the CD earn?', '$5',
        [('$0.50', 'Misplaces the decimal'), ('$40', 'Gives the CD\'s interest'), ('$75', 'Adds both')],
        fb='$40 − $35 = $5 more, in exchange for less access.', calc=1000 * 0.04 - 1000 * 0.035, sub='Return difference'),
    ]),
    math('Find simple interest', 'CD interest and penalties use simple interest over part of a year.', 'grade_7', 10),
  ],
  go=[
    deeper('CD ladders', [
      q('Rosa splits $4,000 into four CDs of $1,000 each, maturing in 1, 2, 3, and 4 years. What is this strategy called?', 'A CD ladder',
        [('A CD pyramid scheme', 'Confuses with fraud'), ('A savings sweep', 'Different product feature'), ('A money market account', 'Confuses CD ladders with a variable-rate account')],
        intro='A CD ladder spreads money across CDs with different maturity dates. One CD matures each year, giving regular access to part of the money, and maturing CDs can be reinvested at current rates.',
        fb='Staggered maturities form a "ladder."', sub='Ladder basics'),
      q('In a 4-rung ladder of $1,000 CDs maturing in years 1–4, how much becomes available each year?', '$1,000',
        [('$4,000', 'Assumes all mature together'), ('$250', 'Divides the rung again'), ('$0', 'Assumes nothing matures until year 4')],
        intro='In a CD ladder, one CD (one "rung") matures each year.',
        fb='One $1,000 CD matures each year (plus its interest).', calc=1000, sub='Access each year'),
      q('Rosa\'s ladder pays 3.8%, 4.0%, 4.1%, and 4.2% on $1,000 each. What is the total interest in the first year (simple interest)?', '$161',
        [('$40.25', 'Averages the rates as dollars'), ('$168', 'Uses 4.2% for all'), ('$152', 'Uses 3.8% for all')],
        fb='$38 + $40 + $41 + $42 = $161.', calc=38 + 40 + 41 + 42, sub='Ladder interest'),
      q('Why might a ladder be better than putting all $4,000 in one 4-year CD?', 'Part of the money becomes available every year without penalty',
        [('A ladder always pays the highest possible rate on every single dollar', 'Overpromises'), ('A ladder has no insurance', 'False'), ('A ladder avoids all taxes', 'False')],
        fb='Ladders balance higher long-term rates with yearly access.', sub='Benefits'),
      q('When the 1-year CD matures, rates have risen. What does a typical ladder strategy do?', 'Reinvest it in a new 4-year CD at the higher rate',
        [('Withdraw it and close the ladder', 'Abandons the plan'), ('Reinvest it for 1 year only, forever', 'Ladder stays short'), ('Break the other CDs early so all the money can be reinvested', 'Pays penalties')],
        fb='Rolling each maturing CD into the longest rung keeps the ladder going and captures new rates.', sub='Reinvesting'),
    ]),
    deeper('U.S. Treasury savings options', [
      q('A $1,000 Treasury bill (T-bill) is bought for $975 and pays $1,000 when it matures. How much does the buyer earn?', '$25',
        [('$975', 'Gives the price'), ('$1,000', 'Gives the face value'), ('$2.50', 'Misplaces the decimal')],
        intro='Treasury bills are short-term loans to the U.S. government. They are sold at a discount, a price below face value, and pay the full face value at maturity. The difference is the earnings. Treasury securities are backed by the U.S. government.',
        fb='$1,000 − $975 = $25.', calc=25, sub='T-bills'),
      q('A T-bill bought for $975 pays $1,000 at maturity, earning $25. What percent of the purchase price is that (nearest hundredth)?', '2.56%',
        [('2.50%', 'Divides by face value'), ('25.00%', 'Misplaces the decimal'), ('97.50%', 'Gives price as a percent of face')],
        intro='The return as a percent of what you paid = earnings ÷ price × 100.',
        fb='$25 ÷ $975 ≈ 0.02564 = 2.56%.', calc=25 / 975 * 100, sub='Return percent'),
      q('Series I savings bonds have a rate that adjusts with inflation. What is the main purpose of that feature?', 'To help savings keep up with rising prices',
        [('To guarantee the bond doubles in value every single year', 'Overpromises'), ('To make the bond a stock investment', 'Misclassifies'), ('To avoid any holding period', 'Ignores holding rules')],
        intro='I bonds are U.S. savings bonds whose rate includes an inflation adjustment that changes every six months. They must be held at least 12 months, and cashing them in before 5 years costs the last 3 months of interest.',
        fb='The inflation-adjusted rate helps protect purchasing power.', sub='I bonds', eff='TreasuryDirect rules as of 2026'),
      q('Under the rules described for I bonds, what happens if one is cashed after 2 years?', 'The last 3 months of interest are lost',
        [('All interest is lost', 'Overstates the penalty'), ('Nothing; there is never a penalty', 'Ignores the rule'), ('It cannot be cashed until it reaches its 30-year final maturity', 'Confuses with final maturity')],
        intro='I bond rules: they cannot be cashed during the first 12 months, and cashing them in before 5 years forfeits the last 3 months of interest.',
        fb='Before 5 years, the last 3 months of interest are forfeited.', sub='I bond penalty', eff='TreasuryDirect rules as of 2026'),
      q('Where can individuals buy Treasury securities directly from the government?', 'TreasuryDirect.gov',
        [('Any social media marketplace', 'Unsafe'), ('A bank\'s certificate of deposit counter only', 'Confuses Treasuries with bank CDs'), ('The FDIC\'s website', 'Confuses deposit insurance with Treasury sales')],
        intro='Individuals can buy Treasury bills, notes, bonds, and savings bonds directly from the U.S. Treasury on its TreasuryDirect website, or through a bank or broker.',
        fb='TreasuryDirect is the Treasury\'s official site for buying securities directly.', sub='Buying Treasuries', how=True),
    ]),
  ],
  nat=('Saving', 'Compare savings products: CDs, money market accounts, and Treasury securities'), nj=['FI'],
  status='time_sensitive', sources=[FDIC, TD], extra=['Building a CD ladder', 'Buying Treasuries on TreasuryDirect'])
